package kz.printlab.dto; import jakarta.validation.constraints.*;
public class RegisterRequest { @NotBlank(message="Укажите email") @Email(message="Некорректный email") @Size(max=255) private String email; @NotBlank(message="Укажите пароль") @Size(min=8,max=72,message="Пароль должен содержать от 8 до 72 символов") @Pattern(regexp="^(?=.*[A-Za-zА-Яа-яЁё])(?=.*[0-9]).*$",message="Пароль должен содержать буквы и цифры") private String password; @NotBlank(message="Повторите пароль") private String confirmPassword;
public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getConfirmPassword(){return confirmPassword;} public void setConfirmPassword(String v){confirmPassword=v;}}
